using System;

namespace RetroIO.Storage.Ndfs.Creation
{
    /// <summary>
    /// Real ND-100 page-0 bootstraps (full 2000-byte boot region, bytes 0..1999), embedded
    /// as base64 so they compile INTO the assembly instead of being read from an external
    /// boot-sectors/*.bin file. Auto-generated from real disk images; do not hand-edit the
    /// base64. A real SMD bootstrap has live code past byte 1024, so the old 1024-byte cut
    /// would not boot; and a relative file path does not resolve when used as a NuGet package.
    /// </summary>
    internal static class NdfsBootBlobs
    {
        /// <summary>Full boot region length in bytes (page-0 bytes 0..1999).</summary>
        public const int BootRegionSize = 2000;

        // Smd -- real PACK-ONE bootstrap (PIOF + IOX 154x).
        private const string SmdB64 =
            "";

        // Winchester -- real Micropolis 1325, ST-506/MFM (PIOF + IOX 50x).
        private const string WinchesterB64 =
            "";

        // Scsi -- real ND-3201 SCSI (PIOF + indirect IOXT).
        private const string ScsiB64 =
            "";

        // Floppy -- real FLOMON BPUN stream.
        private const string FloppyB64 =
            "";

        public static byte[] Smd => Convert.FromBase64String(SmdB64);
        public static byte[] Winchester => Convert.FromBase64String(WinchesterB64);
        public static byte[] Scsi => Convert.FromBase64String(ScsiB64);
        public static byte[] Floppy => Convert.FromBase64String(FloppyB64);
    }
}
